import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { beginModelLoad, endModelLoad } from '../utils/modelLoading';
import { isAppIdle, subscribeAppIdle } from '../utils/idleSleep';

// Plain three.js renderer — deliberately NOT @react-three/fiber: fiber 9
// (via its `its-fine` dependency) statically references React.use, which
// React 18 does not export, so importing fiber breaks the production
// build outright (webpack: "'use' is not exported from 'react'").
// Plain three.js compiles and runs fine on React 18.
//
// The model is framed by its own bounding box: Tripo GLBs arrive at
// arbitrary scale and offset, so the scene re-scales to ~1.8 units tall
// (times `zoom`) and re-centres on the origin.
//
// FULL-BOX FIT (Round 16, Eddie 2026-11-17: "Prime Zero's wings are
// clipped off; some of the other 3D models have clipped wings as
// well"): the camera used to sit at one fixed distance, and the
// hand-tuned `zoom` values on the wide-wing models (Emberwing 1.45,
// Ashwing 1.5, Voltwing 1.3) pushed their wingspans PAST the frame
// — measured at phone aspect, Emberwing's box filled 134% of the
// frame width. The camera now auto-fits: after a model loads, its
// scaled bounding box (horizontal extent as a yaw-proof cylinder
// radius, so the in-scene sway can never swing a wingtip out of
// frame) sets a minimum camera distance at the canvas's real
// aspect, with the arena's 0.94 fit margin. The camera only ever
// dollies BACK from the classic framing, never closer — models
// that already fit render exactly as before, and `zoom` still
// enlarges a model, with the fit as the guarantee that the
// enlargement stops at the frame's edge instead of past it.
//
// PRESENTATION LAW (Eddie, 2026-11-16): a navitar stands UPRIGHT on
// its base, facing front. It may only turn LEFT ↔ RIGHT — a gentle
// in-scene yaw sway of the model group, oscillating within
// ±yawAmpDeg of front on a sine (eased at both ends by the sine
// itself). NEVER a full rotation, NEVER a card-flip, and NEVER
// grab-and-orbit: this viewer has no orbit controls at all — the
// camera framing is the game's, not the user's. (The first version
// had OrbitControls + a continuous 360° turntable; both are gone.)
// The sway is time-based, not frame-based, so it keeps its tempo at
// any frame rate, and it stands down entirely under
// prefers-reduced-motion.
//
// STANDING BASE (same law): every model stands on the soft
// contact shadow under its feet, grounded exactly at the model's
// min.y (no floating, no sinking). QC verified 2026-11-16 that no
// model has a base baked into its GLB (Tidefang's "wave block" and
// Shadowmaw's "smoke base" are portrait-only paint). A model whose
// pose calls for it (Tidefang's coil) can be seated slightly INTO
// the ground via sinkFrac — see utils/navitarArt
// modelPresentationFor.
//
// SHADOW ONLY, NO DISC (Round 36.5 began it on the two stages;
// Round 36.9 Part 3, Eddie 2026-11-20, completes it EVERYWHERE):
// the element-tinted podium disc and its water ripple ring are
// retired on every surface — Stage, shelf, grid, Profile, AR,
// Home. "We should just move to straight shadow no disc." The
// battle arena's ground is a different renderer entirely
// (ElementalWorld), untouched.
const ModelCanvas: React.FC<{
  modelUrl: string;
  // Closer framing for models whose bounding box is dominated by a wide
  // span (the phoenix's wings), which otherwise reads small in the card.
  zoom?: number;
  // Grounded framing (run 2 add-on fix): instead of centring the
  // bounding box, plant the model's feet (box.min.y) at the ground
  // and aim the camera at its mid-height, so in the AR view it
  // STANDS on the ground shadow instead of floating at frame centre.
  // Card viewers omit it and keep the centred framing.
  grounded?: boolean;
  // Yaw sway (presentation law above): amplitude in degrees either
  // side of front, one full left-right-left cycle in yawPeriodS
  // seconds, phase-shifted by yawPhaseS so fighters never sway in
  // sync. Defaults are a gentle ±14° / 9s for plain viewer use; the
  // Navidex Stage passes its per-fighter signature values.
  yawAmpDeg?: number;
  yawPeriodS?: number;
  yawPhaseS?: number;
  // Standing-base tint (element colour, from the caller's palette).
  baseTint?: string;
  // Bare-shadow standing: since Round 36.9 every standing is
  // bare-shadow; the prop remains accepted for caller
  // compatibility and no longer changes what renders.
  bareShadow?: boolean;
  // Water presentation: the ripple ring retired with the disc in
  // Round 36.9; accepted for compatibility, renders nothing.
  ripple?: boolean;
  // Facing correction (radians): Tripo models disagree on which
  // way is front — the caller's presentation registry
  // (utils/navitarArt modelPresentationFor) supplies the yaw that
  // faces this model at the camera. The sway oscillates AROUND it.
  rotationY?: number;
  // Seating: sink the model into its disc by this fraction of its
  // scaled height (Tidefang's coil, ~0.04) so it reads as rising
  // out of the disc rather than balancing on it.
  sinkFrac?: number;
  // Render activity (Round 36.9 Part 7b): when false, the render
  // loop stands DOWN — no rAF, no render — while the scene, the
  // loaded model and the WebGL context stay mounted, so flipping
  // back to active is instant. The Navidex Stage passes
  // active={the 3D face is showing}: in Card mode the canvas used
  // to keep rendering under the card art (battery audit §2).
  // Loading is unaffected — a model still loads and the
  // sanctioned prefetch still warms while inactive.
  active?: boolean;
  onLoaded: () => void;
  onError: () => void;
}> = ({
  modelUrl,
  zoom = 1,
  grounded = false,
  yawAmpDeg = 14,
  yawPeriodS = 9,
  yawPhaseS = 0,
  baseTint = '#12a5c7',
  bareShadow = false,
  ripple = false,
  rotationY = 0,
  sinkFrac = 0,
  active = true,
  onLoaded,
  onError,
}) => {
  const mountRef = useRef<HTMLDivElement>(null);
  // Latest props, read by the long-lived effect/tick without
  // re-running the scene setup when a caller re-renders.
  const propsRef = useRef({
    onLoaded,
    onError,
    yawAmpDeg,
    yawPeriodS,
    yawPhaseS,
    baseTint,
    bareShadow,
    ripple,
    rotationY,
    sinkFrac,
    active,
  });
  propsRef.current = {
    onLoaded,
    onError,
    yawAmpDeg,
    yawPeriodS,
    yawPhaseS,
    baseTint,
    bareShadow,
    ripple,
    rotationY,
    sinkFrac,
    active,
  };
  // The mount effect registers its loop-restarter here so the
  // `active` prop (and the idle-sleep wake) can stand the render
  // loop back up without re-running the scene setup.
  const resumeRef = useRef<(() => void) | null>(null);
  useEffect(() => {
    if (active) resumeRef.current?.();
  }, [active]);

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    let raf = 0;
    let cancelled = false;
    let renderer: THREE.WebGLRenderer | null = null;
    let scene: THREE.Scene | null = null;
    let model: THREE.Group | null = null;
    let retryTimer = 0;
    const reducedMotion =
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const startedAt = performance.now();

    try {
      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    } catch {
      propsRef.current.onError();
      return;
    }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.setClearColor(0x000000, 0);
    mount.appendChild(renderer.domElement);

    scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      42,
      mount.clientWidth / Math.max(mount.clientHeight, 1),
      0.1,
      100
    );
    camera.position.set(0, 0.4, 3.4);
    // No orbit controls (presentation law): the camera is aimed
    // once, at the framing target — the old code let OrbitControls
    // re-aim it every frame; the grounded branch re-aims at the
    // model's mid-height once the box is known.
    camera.lookAt(0, 0, 0);

    // ---- Full-box camera fit (Round 16, see header) -----------
    // The classic framing: target at the origin (or the grounded
    // model's mid-height), camera on the (0, 0.4, 3.4) ray. The
    // fit keeps that ray and only extends its length when the
    // loaded model's bounding box demands it.
    const FIT_DIR = new THREE.Vector3(0, 0.4, 3.4);
    const FIT_DEFAULT_DIST = FIT_DIR.length();
    FIT_DIR.normalize();
    const FIT_MARGIN = 0.9; // the arena's fit margin (ElementalWorld);
    // Round 36.9 Part 1: tightened from 0.94 — the full model bounds,
    // wingspan included, frame with a visible margin of air around
    // them (Eddie: "we give room for them to have full wings").
    let fitBox: { cylR: number; halfH: number; targetY: number } | null = null;
    const applyFit = () => {
      if (!fitBox || !mount) return;
      const aspect = mount.clientWidth / Math.max(mount.clientHeight, 1);
      camera.aspect = aspect;
      const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
      const tanH = tanV * aspect;
      // Distance at which the box's nearest face plane clears
      // both frustum axes: the cylinder radius must fit the
      // horizontal angle, the half-height the vertical, each
      // measured from (distance − radius) so the model's nearest
      // point is what clears the frame.
      const needed =
        fitBox.cylR +
        Math.max(fitBox.halfH / (tanV * FIT_MARGIN), fitBox.cylR / (tanH * FIT_MARGIN));
      const dist = Math.max(FIT_DEFAULT_DIST, needed);
      camera.position.set(FIT_DIR.x * dist, fitBox.targetY + FIT_DIR.y * dist, FIT_DIR.z * dist);
      camera.lookAt(0, fitBox.targetY, 0);
      camera.updateProjectionMatrix();
    };

    scene.add(new THREE.AmbientLight(0xffffff, 0.9));
    const key = new THREE.DirectionalLight(0xffffff, 1.4);
    key.position.set(3, 5, 4);
    scene.add(key);
    const fill = new THREE.DirectionalLight(0xffffff, 0.4);
    fill.position.set(-4, 2, -3);
    scene.add(fill);

    // Soft radial contact shadow texture (drawn once per canvas):
    // a dark centre fading to nothing — the ground-grip under the
    // model's feet, on the podium disc or straight on the field.
    const shadowTexture = (() => {
      const c = document.createElement('canvas');
      c.width = 128;
      c.height = 128;
      const ctx = c.getContext('2d');
      if (ctx) {
        const g = ctx.createRadialGradient(64, 64, 4, 64, 64, 62);
        g.addColorStop(0, 'rgba(0,0,0,0.55)');
        g.addColorStop(0.6, 'rgba(0,0,0,0.28)');
        g.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 128, 128);
      }
      const tex = new THREE.CanvasTexture(c);
      return tex;
    })();

    const loader = new GLTFLoader();
    let loadAttempts = 0;
    // Round 24: this load registers with the global model-loading
    // registry (utils/modelLoading) — the ambient slowdown and the
    // summon surfaces read it. Settled exactly once: on load, on
    // final error, or on unmount, whichever comes first (the retry
    // below does NOT settle — the model is still travelling).
    let loadSettled = false;
    const settleLoad = () => {
      if (!loadSettled) {
        loadSettled = true;
        endModelLoad();
      }
    };
    const loadModel = () => {
      loader.load(
        modelUrl,
        gltf => {
          if (cancelled || !scene) return;
          const box = new THREE.Box3().setFromObject(gltf.scene);
          const size = box.getSize(new THREE.Vector3());
          const center = box.getCenter(new THREE.Vector3());
          const max = Math.max(size.x, size.y, size.z) || 1;
          const scale = (1.8 * zoom) / max;
          gltf.scene.scale.setScalar(scale);
          if (grounded) {
            // Feet at y=0 (min.y grounding, the battle-stage rule),
            // camera raised to the model's mid-height: a ~1.8-unit
            // model in the ~2.6-unit view lands its feet ~85% down
            // the frame, on its podium disc.
            gltf.scene.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);
            const midY = (size.y * scale) / 2;
            camera.position.set(0, midY + 0.4, 3.4);
            camera.lookAt(0, midY, 0);
          } else {
            gltf.scene.position.set(-center.x * scale, -center.y * scale, -center.z * scale);
          }
          // Seating (presentation registry): sink the model into
          // its disc by sinkFrac of its scaled height — the disc
          // top stays on the ground plane, the model's lowest
          // point settles just below it.
          const sink = propsRef.current.sinkFrac * size.y * scale;
          if (sink > 0) gltf.scene.position.y -= sink;
          // Full-box fit (Round 16): record the scaled bounding
          // box — horizontal extent as a yaw-proof cylinder
          // radius (the sway rotates the model in-scene; the
          // cylinder is the widest the box can ever project) —
          // and frame the camera on it. The grounded branch's
          // hand-set camera above is the default this fit starts
          // from and only extends. The sink lowers the box, so
          // it joins the half-height the fit must clear.
          fitBox = {
            cylR: Math.hypot((size.x * scale) / 2, (size.z * scale) / 2),
            halfH: (size.y * scale) / 2 + sink,
            targetY: grounded ? (size.y * scale) / 2 : 0,
          };
          applyFit();
          // Facing: the model's rest yaw is its correction; the
          // tick's sway oscillates around this value.
          gltf.scene.rotation.y = propsRef.current.rotationY;
          model = gltf.scene;
          scene.add(gltf.scene);

          // ---- Standing base -----------------------------------
          // The model's feet in scene space: y=0 when grounded,
          // the bottom of the centred box otherwise. The base sits
          // exactly there — disc top flush with min.y.
          const feetY = grounded ? 0 : -(size.y * scale) / 2;
          const footSpan = Math.max(size.x, size.z) * scale;
          const radius = Math.min(Math.max(footSpan * 0.575, 0.55), 1.4);

          // The contact shadow is EVERY standing's ground-grip —
          // and since Round 36.9 it is the ONLY base: no disc,
          // no ripple ring, on any surface.
          const shadow = new THREE.Mesh(
            new THREE.PlaneGeometry(radius * 2.1, radius * 2.1),
            new THREE.MeshBasicMaterial({
              map: shadowTexture,
              transparent: true,
              depthWrite: false,
            })
          );
          shadow.rotation.x = -Math.PI / 2;
          shadow.position.y = feetY + 0.002;
          shadow.renderOrder = 1;
          scene.add(shadow);

          // Round 36.9 Part 3 (Eddie, 2026-11-20): SHADOW ONLY,
          // NO DISC, EVERYWHERE. The podium disc and its water
          // ripple ring are RETIRED on every surface — grid and
          // shelf cards, Profile, AR, Home, Stage — not just the
          // bare-shadow stages that went first in Round 36.5.
          // Eddie: "sometimes we have the character on a disc and
          // sometimes we have the character on a shadow. I think
          // we should just move to straight shadow no disc." The
          // contact shadow above is now the ONLY standing base.
          // The bareShadow / ripple props stay in the API for
          // caller compatibility; they no longer change what
          // renders. (The battle arena floor is the realm's
          // ground in ElementalWorld, a different renderer —
          // untouched, as before.)

          settleLoad();
          propsRef.current.onLoaded();
        },
        undefined,
        () => {
          if (cancelled) return;
          // ONE automatic retry before giving up (2026-11-16,
          // Round 6): these GLBs run up to ~28 MB — a single
          // network hiccup on a phone used to mark the fighter as
          // "picture forever". A transient failure now heals
          // itself; only a second failure reports the error.
          loadAttempts += 1;
          if (loadAttempts <= 1) {
            retryTimer = window.setTimeout(loadModel, 700);
          } else {
            settleLoad();
            propsRef.current.onError();
          }
        }
      );
    };
    beginModelLoad();
    loadModel();

    const onResize = () => {
      if (!mount || !renderer) return;
      const w = mount.clientWidth;
      const h = Math.max(mount.clientHeight, 1);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
      // The fit is aspect-dependent (Round 16): a narrower canvas
      // needs the camera further back for the same box.
      applyFit();
    };
    window.addEventListener('resize', onResize);
    // Round 36.8: the stage card's focus mode resizes the
    // canvas's CONTAINER without any window resize — observe
    // the mount so the renderer size and the aspect fit
    // follow the box. Idempotent at the standing size.
    const mountObserver =
      typeof ResizeObserver !== 'undefined' ? new ResizeObserver(onResize) : null;
    if (mountObserver && mount) mountObserver.observe(mount);

    // The render loop (Round 36.9 Part 7b + 7e): the loop runs
    // only while this canvas is ACTIVE (its face is the one
    // showing) and the app is AWAKE. Standing down stops the
    // rAF chain entirely — no per-frame JS, no render — while
    // the scene and model stay mounted for an instant return.
    // The sway is time-based, so a resumed loop picks up the
    // correct phase with no jump.
    let loopRunning = false;
    const tick = () => {
      if (cancelled || !propsRef.current.active || isAppIdle()) {
        loopRunning = false;
        return;
      }
      loopRunning = true;
      raf = requestAnimationFrame(tick);
      const t = (performance.now() - startedAt) / 1000;
      if (model) {
        // The yaw sway (presentation law): the MODEL GROUP turns
        // left ↔ right in-scene around its facing correction,
        // sinusoidal — full speed mid-swing, easing to a stop at
        // each end, always upright, never beyond ±amp of front,
        // never a full turn. Reduced motion: holds the correction.
        const {
          yawAmpDeg: amp,
          yawPeriodS: period,
          yawPhaseS: phase,
          rotationY: facing,
        } = propsRef.current;
        model.rotation.y =
          facing +
          (reducedMotion
            ? 0
            : THREE.MathUtils.degToRad(amp) *
              Math.sin(((t + phase) / Math.max(period, 0.1)) * Math.PI * 2));
      }
      if (renderer && scene) renderer.render(scene, camera);
    };
    const startLoop = () => {
      if (cancelled || loopRunning) return;
      loopRunning = true;
      tick();
    };
    resumeRef.current = startLoop;
    // Idle-sleep wake: stand back up the moment the app wakes.
    const unsubscribeIdle = subscribeAppIdle(sleeping => {
      if (!sleeping) startLoop();
    });
    tick();

    return () => {
      cancelled = true;
      unsubscribeIdle();
      if (resumeRef.current === startLoop) resumeRef.current = null;
      settleLoad();
      cancelAnimationFrame(raf);
      window.clearTimeout(retryTimer);
      window.removeEventListener('resize', onResize);
      mountObserver?.disconnect();
      if (scene) {
        scene.traverse(obj => {
          const mesh = obj as THREE.Mesh;
          if (mesh.geometry) mesh.geometry.dispose();
          const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
          if (Array.isArray(material)) material.forEach(m => m.dispose());
          else if (material) material.dispose();
        });
      }
      shadowTexture.dispose();
      renderer?.dispose();
      // Actually RELEASE the WebGL context (Round 6 fix): dispose()
      // alone leaves the context alive until the browser's lazy GC,
      // and mobile Safari caps live contexts (~8) — swiping a
      // roster of 3D fighters used to exhaust them, after which
      // new renderer creation threw and fighters fell back to
      // portraits for the rest of the session.
      renderer?.forceContextLoss();
      if (renderer && mount.contains(renderer.domElement)) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, [modelUrl, zoom, grounded]);

  return <div ref={mountRef} style={{ width: '100%', height: '100%' }} />;
};

export default ModelCanvas;
